4	/// The two ways "New Project" can resolve a path (issue #103):
5	/// - `existing`: the path must already be a Git/JJ repo (the historical behaviour).
6	/// - `createNew`: a missing path is created and git-initialized by the CLI.
7	enum AddProjectMode: CaseIterable, Identifiable {
8	  case existing
9	  case createNew
10	  var id: Self { self }
11	}
12	
13	/// Pure presentation rules for `AddProjectSheet`, extracted so path normalization,
14	/// the enable-until-valid gate, and the per-mode footer are unit-testable without
15	/// rendering SwiftUI (mirrors `DeleteProjectSheetModel`).
16	enum AddProjectSheetModel {
17	  /// Expand a leading "~" or "~/" to the home directory and trim surrounding
18	  /// whitespace. Only those two forms are expanded — matching the CLI's
19	  /// `config.CanonicalPath`, which also leaves "~user" untouched — so the path the
20	  /// dialog validates and sends lines up with what the CLI canonicalizes.
21	  static func normalize(_ path: String) -> String {
22	    let trimmed = path.trimmingCharacters(in: .whitespacesAndNewlines)
23	    if trimmed == "~" || trimmed.hasPrefix("~/") {
24	      return (trimmed as NSString).expandingTildeInPath
25	    }
26	    return trimmed
27	  }
28	
29	  /// Whether "Add Project" is enabled: a non-empty, absolute path. In `createNew`
30	  /// mode a path that already exists as a regular file is rejected (the CLI would
31	  /// return NotADirectory — fail fast before the round-trip).
32	  static func isValid(mode: AddProjectMode, path: String) -> Bool {
33	    let p = normalize(path)
34	    guard !p.isEmpty, p.hasPrefix("/") else { return false }
35	    if mode == .createNew {
36	      var isDir: ObjCBool = false
37	      if FileManager.default.fileExists(atPath: p, isDirectory: &isDir), !isDir.boolValue {
38	        return false
39	      }
40	    }
41	    return true
42	  }
43	
44	  static func footer(mode: AddProjectMode) -> String {
45	    switch mode {
46	    case .existing:
47	      return "Choose or type the full path to an existing Git or Jujutsu repository."
48	    case .createNew:
49	      return
50	        "Type the full path for the new project. If the folder doesn't exist it's created and "
51	        + "initialized as a Git repository."
52	    }
53	  }
54	}
