56	/// The "New Project" dialog (issue #103). Two modes share one editable path field:
57	/// "From existing path…" adds an existing repo (the prior folder-picker behaviour),
58	/// and "Create new directory…" lets the user type a path that the CLI creates and
59	/// git-initializes if it doesn't exist. "Choose…" opens a folder picker that fills
60	/// the field (the project itself in existing mode, or a base to extend in create mode).
61	///
62	/// `onAdd(path, create)` passes the normalized path and whether create-mode is on;
63	/// the parent owns dismissing the sheet and calling the store.
64	struct AddProjectSheet: View {
65	  let onAdd: (_ path: String, _ create: Bool) -> Void
66	  let onCancel: () -> Void
67	
68	  @State private var mode: AddProjectMode = .existing
69	  @State private var path: String = ""
70	  @State private var showChooser = false
71	  @FocusState private var pathFieldFocused: Bool
72	
73	  private var normalized: String { AddProjectSheetModel.normalize(path) }
74	  private var isValid: Bool { AddProjectSheetModel.isValid(mode: mode, path: path) }
75	
76	  private func submit() {
77	    guard isValid else { return }
78	    onAdd(normalized, mode == .createNew)
79	  }
