82	    VStack(alignment: .leading, spacing: 16) {
83	      HStack(alignment: .top, spacing: 12) {
84	        Image(systemName: "folder.badge.plus")
85	          .font(.system(size: 30))
86	          .foregroundStyle(.tint)
87	          .accessibilityHidden(true)
88	        VStack(alignment: .leading, spacing: 4) {
89	          Text("New Project")
90	            .font(.headline)
91	          Text("Add an existing repository, or create a new project directory.")
92	            .font(.callout)
93	            .foregroundStyle(.secondary)
94	        }
95	      }
96	
97	      Picker("Source", selection: $mode) {
98	        Text("From existing path…").tag(AddProjectMode.existing)
99	        Text("Create new directory…").tag(AddProjectMode.createNew)
100	      }
101	      .pickerStyle(.radioGroup)
102	      .labelsHidden()
103	      .accessibilityIdentifier("addProject.modePicker")
104	
105	      VStack(alignment: .leading, spacing: 6) {
106	        Text(mode == .existing ? "Repository path" : "New project path")
107	          .font(.subheadline.weight(.semibold))
108	        HStack(spacing: 8) {
109	          TextField("/path/to/project", text: $path)
110	            .textFieldStyle(.roundedBorder)
111	            .focused($pathFieldFocused)
112	            .lineLimit(1)
113	            .onSubmit(submit)
114	            .accessibilityIdentifier("addProject.pathField")
115	          Button("Choose…") { showChooser = true }
116	            .accessibilityIdentifier("addProject.chooseButton")
117	        }
118	        Text(AddProjectSheetModel.footer(mode: mode))
119	          .font(.callout)
120	          .foregroundStyle(.secondary)
121	          .fixedSize(horizontal: false, vertical: true)
122	      }
123	
124	      Divider()
125	      HStack {
126	        Spacer()
127	        Button("Cancel") { onCancel() }
128	          .keyboardShortcut(.cancelAction)
129	        Button("Add Project", action: submit)
130	          .keyboardShortcut(.defaultAction)
131	          .buttonStyle(.borderedProminent)
132	          .disabled(!isValid)
133	          .accessibilityIdentifier("addProject.confirmButton")
134	      }
135	    }
136	    .padding(20)
137	    .frame(width: 460)
138	    .onAppear { pathFieldFocused = true }
139	    .fileImporter(isPresented: $showChooser, allowedContentTypes: [.folder]) { result in
140	      // Existing mode: the picked folder IS the project. Create mode: it's a base
141	      // directory the user extends with a new folder name in the field.
142	      if case .success(let url) = result {
143	        path = url.path
144	      }
145	    }
146	  }
