  func testOpensOnLaunchSeedWithNoProjects() {
    let seed = WindowSeed.launch
    XCTAssertTrue(
      RootWindow.shouldOpenOnboarding(seed: seed, hasCompleted: false, projectsEmpty: true))
  }

  func testNeverOpensOnANonLaunchSeed() {
    let restoring = WindowSeed.restoring(key: UUID())
    XCTAssertFalse(
      RootWindow.shouldOpenOnboarding(seed: restoring, hasCompleted: false, projectsEmpty: true))
