  func testDoesNotOpenOnLaunchSeedWhenAlreadyCompleted() {
    let seed = WindowSeed.launch
    XCTAssertFalse(
      RootWindow.shouldOpenOnboarding(seed: seed, hasCompleted: true, projectsEmpty: true))
  }
}

