import XCTest

/// The first-run onboarding wizard (issue #151).
///
/// Two groups: the override-driven walkthrough (fixture mode, deterministic, fast) and the
/// persistence contract itself (non-fixture mode, real gate) — the acceptance criterion this
/// feature exists for ("still shows next launch if closed early; never shows again once finished").
///
/// The persistence group can't use fixture mode: `UITestFixture.applyFixtureDefaults` pins
/// `Defaults[.hasCompletedOnboarding] = true` unconditionally whenever fixture mode is active (to
/// protect unrelated fixture tests, e.g. `NewWorkroomDialogUITests`' `-WorkroomUITestNoProjects 1`),
/// which would defeat a test that needs the REAL, unpinned value of that same key. `Defaults` is not
/// isolated by a throwaway `HOME` either (see `ThemePickerUITests`'s doc comment) — a `defaults`
/// shell-out is what actually resets it between runs, the same reset issue #151's own plan documents
/// for manual verification.
final class OnboardingUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private let bundleID = "com.developwithstyle.workroom.dev"

  // MARK: Fixture-mode walkthrough

  private func launchedFixtureApp(extraArgs: [String] = []) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1", "-WorkroomUITestNoProjects", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launchArguments += extraArgs
    app.launch()
    return app
  }

  private var onboardingWindow: XCUIElement {
    XCUIApplication().windows.matching(identifier: "onboarding.window").firstMatch
  }

  /// Walks Welcome → Tour → skip Add Project → Done → Get Started, forced via the override so it's
  /// independent of the real gate/Defaults state.
  func testWalkthroughSkippingAddProjectClosesTheWindow() {
    let app = launchedFixtureApp(extraArgs: ["-WorkroomUITestOnboarding", "show"])
    let window = app.windows["onboarding.window"]
    XCTAssertTrue(window.waitForExistence(timeout: 10), "onboarding window should open")

    app.buttons["Next"].click()  // welcome -> tour
    app.buttons["Next"].click()  // tour -> addProject
    app.buttons["Skip"].click()  // addProject -> done
    XCTAssertTrue(app.buttons["Get Started"].waitForExistence(timeout: 4))
    app.buttons["Get Started"].click()

    let exp = XCTNSPredicateExpectation(predicate: NSPredicate(format: "exists == false"), object: window)
    XCTAssertEqual(
      XCTWaiter().wait(for: [exp], timeout: 4), .completed, "window should close on Get Started")
  }

  /// Walks to the real Add Project step and adds a project, asserting auto-advance to Done — the
  /// success path of `OnboardingWindow.handleAdd`.
  func testAddingARealProjectAdvancesToDone() throws {
    let app = launchedFixtureApp(extraArgs: ["-WorkroomUITestOnboarding", "show"])
    let window = app.windows["onboarding.window"]
    XCTAssertTrue(window.waitForExistence(timeout: 10))

    app.buttons["Next"].click()  // welcome -> tour
    app.buttons["Next"].click()  // tour -> addProject

    let projectDir = FileManager.default.temporaryDirectory
      .appendingPathComponent("workroom-onboarding-uitest-\(UUID().uuidString)", isDirectory: true)
    defer { try? FileManager.default.removeItem(at: projectDir) }

    let pathField = app.textFields["addProject.pathField"]
    XCTAssertTrue(pathField.waitForExistence(timeout: 4))
    app.radioButtons.element(matching: NSPredicate(format: "label CONTAINS 'Create new directory'"))
      .click()
    pathField.click()
    pathField.typeText(projectDir.path)

    let addButton = app.buttons["Add Project"]
    XCTAssertTrue(addButton.waitForExistence(timeout: 4))
    XCTAssertTrue(addButton.isEnabled, "a valid create-mode path should enable Add Project")
    addButton.click()

    XCTAssertTrue(app.buttons["Get Started"].waitForExistence(timeout: 10), "should auto-advance to Done")
  }

  // MARK: Persistence (the acceptance criterion)

  private func resetHasCompletedOnboardingDefault() {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/defaults")
    process.arguments = ["delete", bundleID, "onboarding.hasCompleted"]
    try? process.run()
    process.waitUntilExit()
  }

  private func launchedNonFixtureApp(home: URL) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchEnvironment["HOME"] = home.path
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    return app
  }

  /// Closing the wizard before it reaches Done leaves the completion flag unset, so it reopens on
  /// the next launch — the "still show again if not finished" half of the contract.
  func testClosingEarlyReopensOnNextLaunch() throws {
    resetHasCompletedOnboardingDefault()
    let home = FileManager.default.temporaryDirectory
      .appendingPathComponent("workroom-onboarding-home-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: home, withIntermediateDirectories: true)
    defer {
      try? FileManager.default.removeItem(at: home)
      resetHasCompletedOnboardingDefault()
    }

    let app = launchedNonFixtureApp(home: home)
    let window = app.windows["onboarding.window"]
    XCTAssertTrue(window.waitForExistence(timeout: 10), "a fresh HOME with no projects should show onboarding")
    app.terminate()

    let relaunched = launchedNonFixtureApp(home: home)
    XCTAssertTrue(
      relaunched.windows["onboarding.window"].waitForExistence(timeout: 10),
      "closing before Done should leave the wizard showing again next launch")
  }

  /// Reaching Done (by any path) sets the flag on entry, so it does NOT reopen on the next launch —
  /// the "never shows again once finished" half of the contract.
  func testReachingDoneNeverReopens() throws {
    resetHasCompletedOnboardingDefault()
    let home = FileManager.default.temporaryDirectory
      .appendingPathComponent("workroom-onboarding-home-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: home, withIntermediateDirectories: true)
    defer {
      try? FileManager.default.removeItem(at: home)
      resetHasCompletedOnboardingDefault()
    }

    let app = launchedNonFixtureApp(home: home)
    let window = app.windows["onboarding.window"]
    XCTAssertTrue(window.waitForExistence(timeout: 10))
    app.buttons["Next"].click()  // welcome -> tour
    app.buttons["Next"].click()  // tour -> addProject
    app.buttons["Skip"].click()  // addProject -> done (sets the flag on entry)
    XCTAssertTrue(app.buttons["Get Started"].waitForExistence(timeout: 4))
    app.terminate()  // closed via terminate, NOT the Get Started button — flag must already be set

    let relaunched = launchedNonFixtureApp(home: home)
    XCTAssertTrue(relaunched.wait(for: .runningForeground, timeout: 10))
    XCTAssertFalse(
      relaunched.windows["onboarding.window"].waitForExistence(timeout: 4),
      "reaching Done should mark onboarding complete regardless of how the window was later closed")
  }
}

