/// Walks to the real Add Project step and adds a project, asserting auto-advance to Done — the
/// success path of `OnboardingWindow.handleAdd`.
///
/// `handleAdd` routes through `WindowRegistry.shared.lastActiveStore.addProject`, which calls the
/// REAL bundled CLI regardless of fixture mode (`AppStore.addProject` has no `UITestFixture.isActive`
/// guard — only the initial project-list load does) — the CLI has no config-path override, so this
/// genuinely registers `projectDir` in the developer's real `~/.config/workroom/config.json`. The
/// temp directory itself is cleaned up via `defer`, but the config ENTRY needs its own explicit
/// removal or it's left dangling (pointing at a now-deleted directory) forever.
func testAddingARealProjectAdvancesToDone() throws {
  let app = launchedApp(extraArgs: ["-WorkroomUITestOnboarding", "show"])
  let window = app.windows["onboarding.window"]
  XCTAssertTrue(window.waitForExistence(timeout: 10))

  window.buttons["Next"].click()  // welcome -> tour
  window.buttons["Next"].click()  // tour -> addProject

  let projectDir = FileManager.default.temporaryDirectory
    .appendingPathComponent("workroom-onboarding-uitest-\(UUID().uuidString)", isDirectory: true)
  defer {
    try? FileManager.default.removeItem(at: projectDir)
    removeFromRealCLIConfig(projectPath: projectDir.path)
  }

  let pathField = window.textFields["addProject.pathField"]

/// Removes a single project entry from the real `~/.config/workroom/config.json` by path — the
/// only cleanup available since the bundled CLI has no config-path override to isolate against
/// instead (see the doc comment on `testAddingARealProjectAdvancesToDone`). Edits the JSON directly
/// rather than shelling out to `workroom delete-project`, to avoid depending on locating the bundled
/// binary inside the built app from a UI test. Best-effort: swallows errors rather than failing an
/// otherwise-passing test over cleanup of a file this test doesn't own.
private func removeFromRealCLIConfig(projectPath: String) {
  let configURL = FileManager.default.homeDirectoryForCurrentUser
    .appendingPathComponent(".config/workroom/config.json")
  guard let data = try? Data(contentsOf: configURL),
    var json = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
  else { return }
  guard json.removeValue(forKey: projectPath) != nil else { return }
  try? JSONSerialization.data(withJSONObject: json, options: [.prettyPrinted]).write(to: configURL)
}

